# owner: platform
"""Snap span edges to a fixed step and label the result for payroll."""

from typing import Iterable, List

from hourglass.parsing import format_span
from hourglass.models import Span

MINUTES_PER_HOUR = 60

def _check_step(step_minutes: int) -> None:
    """Refuse steps that are not positive whole numbers dividing an hour."""
    valid = isinstance(step_minutes, int) and step_minutes > 0
    if not valid or MINUTES_PER_HOUR % step_minutes:
        raise ValueError(f"step must divide 60 evenly, got {step_minutes!r}")

def _snap(minutes: int, step_minutes: int) -> int:
    """Nearest multiple of the step. Exact halves round up."""
    return (minutes + step_minutes // 2) // step_minutes * step_minutes

def _snap_span(span: Span, step_minutes: int) -> Span:
    start = _snap(span.start, step_minutes)
    end = _snap(span.end, step_minutes)
    if start >= end:
        text = format_span(span)
        raise ValueError(f"{text} rounds to nothing at {step_minutes} minutes")
    return Span(start, end)

def _label(span: Span) -> str:
    hours, rest = divmod(span.minutes, MINUTES_PER_HOUR)
    return f"{format_span(span)} ({hours}h {rest}m)"

# ---
def label_rounded_spans(spans: Iterable[Span], step_minutes: int) -> List[str]:
    """Snap each start and end to the step and label each span."""
    _check_step(step_minutes)
    return [_label(_snap_span(span, step_minutes)) for span in spans]
